{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 10,
      "text_ar": "لأنكم ترون أن قدسنا قد خرب، ومذبحنا هدم، وهيكلنا دمر،",
      "verse": 21
    },
    {
      "chapter": 10,
      "text_ar": "وقد حط عودنا، وسكت تسبيحنا، وانتهى فرحنا، وانطفأ نور منارتنا، ونهب تابوت عهدنا، ونجست أقداسنا، ودنس الاسم الذي ندعى به، وعامل أحرارنا باحتقار، وأحرق كهنتنا، وذهب لاويونا إلى السبي، ونجست عذارانا واغتصبت نساؤنا، وسبي أبرارنا، وأسلم صغارنا، واستعبد شباننا، وأقوياؤنا صاروا ضعفاء.",
      "verse": 22
    },
    {
      "chapter": 10,
      "text_ar": "وما هو أعظم من ذلك كله، فإن ختم صهيون قد فقد الآن ختم كرامتها، وسلمت إلى أيدي مبغضينا.",
      "verse": 23
    },
    {
      "chapter": 10,
      "text_ar": "لذلك انفضوا عنكم ثقلكم العظيم، واطرحوا عنكم كثرة الأحزان، لكي يرحمكم القدير مرة أخرى، ويعطيكم العلي راحة، بل طمأنينة من شقائكم.",
      "verse": 24
    },
    {
      "chapter": 10,
      "text_ar": "وحدث بينما كنت أتكلم معها، إذا وجهها يبدأ فجأة في الإشراق جدا، ولمح محياها كالبَرْق، حتى خفت جدا منها، وتعجبت مما يعنيه هذا.",
      "verse": 25
    }
  ]
}
